// EmbedContainer.tsx (template v2)
//
// Generated by rjui_tools `rjui init`. Container for the `Embed` view type.
// Hosts another screen as a region of the parent layout; the embedded screen
// owns its own ViewModel via React hook scoping.
//
// Contracts (per jsonui-cli/docs/plans/2026-05-11-embed-feature.md §16 and
// the v1.5 isolated design 2026-07-24-v1-unsupported/04a-design.md):
// - `screen` is the layout JSON filename (snake_case).
// - `params` is a record tree (nested literal objects allowed; bindings
//   resolve at leaves — validated by the CLI). The embedded VM hook may call
//   `useEmbeddedScreenContext().params` to access them, and react via its
//   own useEffect. VMs that don't read context simply ignore them.
// - `events` are emitted by the embedded VM via
//   `useEmbeddedScreenContext().emit(name, payload)`. The parent's
//   `eventBridge` prop routes them to handlers.
// - `navigationMode` 'delegate' (default) bounds back-navigation at the
//   embed boundary. 'isolated' (template v2) gives the embed a private
//   in-memory stack: push stays inside the embed, pop stops at the stack
//   root (the embed never closes itself), the URL is NOT synced and the
//   browser back button always drives the host router's history — both by
//   design (cross-platform gesture delegation contract).

import React, { createContext, useContext, useMemo, useState } from 'react';

export type EmbedNavigationMode = 'delegate' | 'isolated';

export interface EmbeddedEvent {
  type: string;
  payload?: Record<string, unknown>;
}

export interface EmbeddedNavigationDelegate {
  /** True when in delegate mode — pop is bounded at the embed. */
  boundedAtEmbed: boolean;
  /** Embedded VMs/navigators consult this before driving the parent router. */
  shouldBoundPop: (internalPushDepth?: number) => boolean;
}

/** A pushable entry on an isolated embed's private stack. */
export interface EmbedStackEntry {
  screen: string;
  params: Record<string, unknown>;
}

/**
 * The private navigation stack of an isolated embed (template v2).
 *
 * The cross-platform contract (conformance-tested): push appends to THIS
 * stack, pop stops at the stack root (the embed itself never closes),
 * `depth` reports the number of pushed entries. Null in delegate mode.
 */
export interface EmbedNavigator {
  depth: number;
  push: (screen: string, params?: Record<string, unknown>) => void;
  pop: () => void;
  popToRoot: () => void;
}

export interface EmbeddedScreenContextValue {
  embedId: string;
  screen: string;
  params: Record<string, unknown>;
  navigationDelegate: EmbeddedNavigationDelegate;
  emit: (name: string, payload?: Record<string, unknown>) => void;
  /**
   * Private stack of an isolated embed; null in delegate mode (and when
   * the screen is shown standalone). Embedded VMs route push/pop here
   * when present instead of the host router.
   */
  navigator: EmbedNavigator | null;
}

const EmbeddedScreenContext = createContext<EmbeddedScreenContextValue | null>(null);

/**
 * Hook used by embedded screens / their VMs to access init params, emit
 * events back to the parent, and consult the nav boundary.
 *
 * Returns null when the screen is shown standalone (not embedded).
 */
export function useEmbeddedScreenContext(): EmbeddedScreenContextValue | null {
  return useContext(EmbeddedScreenContext);
}

/**
 * Hook for embedded VMs to reach the isolated embed's private stack.
 * Returns null in delegate mode / standalone (template v2 export — its
 * presence is the version-skew guard for isolated-mode generated code).
 */
export function useEmbedNavigator(): EmbedNavigator | null {
  return useContext(EmbeddedScreenContext)?.navigator ?? null;
}

/**
 * Hook for embedded VMs to receive init params on mount and on params change.
 * VMs that implement an `applyInitParams` method on a ref can drive it from
 * this hook's effect callback. No-op when not embedded.
 */
export function useEmbeddedInitParams(
  apply: (params: Record<string, unknown>) => void,
): void {
  const ctx = useContext(EmbeddedScreenContext);
  const params = ctx?.params;
  // Stable serialization so the effect only fires on actual content change.
  const fingerprint = params ? JSON.stringify(sortKeys(params)) : null;
  React.useEffect(() => {
    if (params && Object.keys(params).length > 0) apply(params);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fingerprint]);
}

function sortKeys(obj: Record<string, unknown>): Record<string, unknown> {
  return Object.keys(obj)
    .sort()
    .reduce<Record<string, unknown>>((acc, k) => {
      acc[k] = obj[k];
      return acc;
    }, {});
}

/** Maps a pushed screen name to the component that renders it. */
export type EmbedScreenResolver = (entry: EmbedStackEntry) => React.ReactNode;

/**
 * Build a screen resolver from a screen-name → component table (template v2
 * export; generated isolated call sites reference this, so type-checking
 * against a v1 template fails instead of silently degrading to delegate).
 * Unknown screens render an explicit error box — never a silent no-op.
 */
export function buildEmbedScreenResolver(
  table: Record<string, React.ComponentType>,
): EmbedScreenResolver {
  return (entry) => {
    const Component = table[entry.screen];
    if (!Component) {
      return (
        <div style={{ background: '#c00', color: '#fff', padding: 8 }} data-embed-error="unresolved-screen">
          Embed: no screen resolver entry for pushed screen &apos;{entry.screen}&apos;
        </div>
      );
    }
    return <Component />;
  };
}

export interface EmbedContainerProps {
  /** Unique id of this embed slot within the parent layout. */
  embedId: string;
  /** Layout JSON filename (snake_case, no extension) of the embedded screen. */
  screen: string;
  /** Init params handed to the embedded screen. */
  params?: Record<string, unknown>;
  /** How navigation from the embedded screen is wired. */
  navigationMode?: EmbedNavigationMode;
  /**
   * Resolves pushed stack entries to rendered screens (isolated mode).
   * Pushed entries without a resolver render an explicit error box.
   */
  screenResolver?: EmbedScreenResolver;
  /** Receives events emitted by the embedded VM. */
  eventBridge?: (event: EmbeddedEvent) => void;
  /** Optional className applied to the container div. */
  className?: string;
  /** The embedded screen component. */
  children: React.ReactNode;
}

export const EmbedContainer: React.FC<EmbedContainerProps> = ({
  embedId,
  screen,
  params,
  navigationMode = 'delegate',
  screenResolver,
  eventBridge,
  className,
  children,
}) => {
  // Isolated mode: the embed owns a private in-memory stack. Stack lifetime
  // == component identity (resets on unmount); the URL is never synced.
  const [stack, setStack] = useState<EmbedStackEntry[]>([]);

  const navigator = useMemo<EmbedNavigator | null>(() => {
    if (navigationMode !== 'isolated') return null;
    return {
      get depth() {
        return stack.length;
      },
      push: (pushedScreen, pushedParams) =>
        setStack((prev) => [...prev, { screen: pushedScreen, params: pushedParams ?? {} }]),
      // Bounded at the embed stack root: popping at depth 0 is a no-op —
      // the embed never closes itself.
      pop: () => setStack((prev) => (prev.length > 0 ? prev.slice(0, -1) : prev)),
      popToRoot: () => setStack((prev) => (prev.length > 0 ? [] : prev)),
    };
  }, [navigationMode, stack]);

  const ctxValue = useMemo<EmbeddedScreenContextValue>(() => {
    const navigationDelegate: EmbeddedNavigationDelegate = {
      boundedAtEmbed: navigationMode === 'delegate',
      shouldBoundPop: (internalPushDepth = 0) =>
        navigationMode === 'delegate' && internalPushDepth === 0,
    };
    return {
      embedId,
      screen,
      params: params ?? {},
      navigationDelegate,
      emit: (name, payload) => eventBridge?.({ type: name, payload }),
      navigator,
    };
  }, [embedId, screen, params, navigationMode, eventBridge, navigator]);

  const top = stack.length > 0 ? stack[stack.length - 1] : null;
  const isolatedContent =
    top !== null ? (
      screenResolver ? (
        // Pushed entries get their params via a nested context so
        // useEmbeddedInitParams works for pushed screens too.
        <EmbeddedScreenContext.Provider value={{ ...ctxValue, screen: top.screen, params: top.params }}>
          {screenResolver(top)}
        </EmbeddedScreenContext.Provider>
      ) : (
        <div style={{ background: '#c00', color: '#fff', padding: 8 }} data-embed-error="no-screen-resolver">
          Embed: no screenResolver for pushed screen &apos;{top.screen}&apos;
        </div>
      )
    ) : null;

  return (
    <EmbeddedScreenContext.Provider value={ctxValue}>
      <div
        data-embed-id={embedId}
        data-embed-screen={screen}
        data-embed-navigation-mode={navigationMode}
        data-embed-stack-depth={navigationMode === 'isolated' ? stack.length : undefined}
        className={className}
      >
        {/* The embed root stays mounted underneath pushed entries so its
            hook state survives push/pop round trips (parity with iOS
            NavigationStack / Android SaveableStateHolder). */}
        <div style={top !== null ? { display: 'none' } : undefined} data-embed-stack-level="root">
          {children}
        </div>
        {isolatedContent !== null && (
          <div data-embed-stack-level={stack.length}>{isolatedContent}</div>
        )}
      </div>
    </EmbeddedScreenContext.Provider>
  );
};

export default EmbedContainer;
